@Bean
public SimpleClientHttpRequestFactory createHttpRequestFactory() {
    SimpleClientHttpRequestFactory clientHttpRequestFactory = new SimpleClientHttpRequestFactory();
    clientHttpRequestFactory.setConnectTimeout(connectTimeout);
    clientHttpRequestFactory.setReadTimeout(readTimeout);
    return clientHttpRequestFactory;
}

@Bean
public HttpClientBuilder createHttpClientBuilder(PoolingHttpClientConnectionManager pollingConnectionManager) {
    HttpClientBuilder httpClientBuilder = HttpClientBuilder.create();
    httpClientBuilder.setConnectionManager(pollingConnectionManager);
    httpClientBuilder.setRetryHandler(new DefaultHttpRequestRetryHandler(2, true));
    return httpClientBuilder;
}

@Bean
public HttpClient createHttpClient(HttpClientBuilder httpClientBuilder) {
    return httpClientBuilder.build();
}


@Bean
public PoolingHttpClientConnectionManager createPoolingHttpClientConnectionManager() {
    PoolingHttpClientConnectionManager poolingHttpClientConnectionManager = new PoolingHttpClientConnectionManager();
    poolingHttpClientConnectionManager.setMaxTotal(2000);
    poolingHttpClientConnectionManager.setDefaultMaxPerRoute(2000);
    return poolingHttpClientConnectionManager;
}

public void pushOrder(OrderSyncReq req) {
    PriceSysResult result = priceSysClient.pushOrder(req);
    // 上游返回 null 不允许继续往下走，边界处立刻变成可识别的业务异常
    if (result == null) {
        throw new BizException(ErrorCode.PRICE_SYS_ERROR, "价格系统调用失败，请稍后重试");
    }
    // 成功判定收紧成双条件：既要状态成功，也要带业务单号
    if (!result.isSuccess() || StringUtils.isBlank(result.getOrderNo())) {
        log.error("pushOrder rejected, reqNo: {}, success: {}, orderNo: {}",
                req.getReqNo(), result.isSuccess(), result.getOrderNo());
        throw new BizException(ErrorCode.PRICE_SYS_ERROR,
                StringUtils.defaultIfBlank(result.getMsg(), "价格系统未返回单号"));
    }
    log.info("pushOrder success, reqNo: {}, orderNo: {}", req.getReqNo(), result.getOrderNo());
}
